#!/usr/bin/env python3 -I
"""Extracts the latest upstream Signal Desktop SQL schema (DATABASE_SCHEMA.md, generated by
upstream scripts/generate-db-schema.mjs) into a Swift migration for SignalCore.

Changes from upstream, both deliberate:
  * FTS5 tokenizer 'signal_tokenizer' (a native Desktop extension) -> 'unicode61 remove_diacritics 2';
  * sqlite_* internal objects are skipped (SQLite creates them);
  * FTS5 shadow tables (<fts>_data/_idx/_content/_docsize/_config) are skipped:
    CREATE VIRTUAL TABLE ... USING fts5 creates them itself.
"""
import re, sys, os
root = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
src = open(os.path.join(root, "Signal-Desktop/DATABASE_SCHEMA.md")).read()
blocks = re.findall(r"<summary>(Table|Index|Trigger|View|Virtual Table)?:?\s*([^<]*)</summary>\s*```sql\n(.*?)\n```", src, re.S)
tables, virtual, indexes, triggers, views = [], [], [], [], []
for kind, name, sql in blocks:
    sql = sql.strip()
    first = sql.split(None, 3)
    if "sqlite_" in name.split("→")[-1].strip()[:7] or re.match(r"CREATE TABLE sqlite_", sql):
        continue
    m = re.match(r"CREATE TABLE '?(\w+)_(data|idx|content|docsize|config)'?", sql)
    if m and re.search(r"CREATE VIRTUAL TABLE %s USING fts5" % re.escape(m.group(1)), src):
        continue
    sql = sql.replace("tokenize = 'signal_tokenizer'", "tokenize = 'unicode61 remove_diacritics 2'")
    if sql.startswith("CREATE VIRTUAL TABLE"): virtual.append(sql)
    elif sql.startswith("CREATE TABLE"): tables.append(sql)
    elif re.match(r"CREATE (UNIQUE )?INDEX", sql): indexes.append(sql)
    elif sql.startswith("CREATE TRIGGER"): triggers.append(sql)
    elif sql.startswith("CREATE VIEW"): views.append(sql)
    else: raise SystemExit("unknown statement: " + sql[:60])
ordered = tables + virtual + views + indexes + triggers
version = re.search(r"SCHEMA_VERSIONS|version", src)
out = ["// Generated by Tools/gen-db-schema.py from Signal-Desktop/DATABASE_SCHEMA.md. Do not edit.",
       f"// {len(tables)} tables, {len(virtual)} virtual tables, {len(views)} views, {len(indexes)} indexes, {len(triggers)} triggers.",
       "", "enum UpstreamSchema {", "    static let statements: [String] = ["]
for s in ordered:
    out.append('        """')
    out += ["        " + line if line else "" for line in s.split("\n")]
    out.append('        """,')
out += ["    ]", "}", ""]
open(os.path.join(root, "Packages/SignalCore/Sources/SignalCore/Database/UpstreamSchema.generated.swift"), "w").write("\n".join(out))
print(len(tables), "tables", len(virtual), "virtual", len(views), "views", len(indexes), "indexes", len(triggers), "triggers")
